import pandas as pd
pool = pd.read_csv('alloy_pair_constrained_pool.csv')
prices = {'C': 0.5, 'Mn': 2, 'Si': 2.2, 'Cr': 9, 'Ni': 17, 'Mo': 25, 'V': 30, 'Nb': 45, 'Co': 33, 'Al': 2.4, 'Ti': 12, 'Cu': 9}
def calc(row):
    return sum(row[e]*p for e, p in prices.items())
pool['cost'] = pool.apply(calc, axis=1)

for cid in ['c068', 'c092', 'c075', 'c064', 'c044']:
    row = pool[pool['candidate_id'] == cid].iloc[0]
    print(f"{cid} - Mo: {row['Mo']}, Cost: {row['cost']}")

EOF
python check.py

